parameters.jsCode:
const serper2Data = $json;
const organic2 = serper2Data.organic || [];

const results2 = organic2.slice(0, 8).map(r => ({
  title: r.title || '',
  link: r.link || '',
  snippet: r.snippet || '',
  position: r.position || 0
}));

const results1 = $('Extraire Resultats 1').first().json.results1 || [];

const allResults = [...results1, ...results2];

const concurrentsText = allResults.map((r, i) =>
  (i + 1) + '. TITRE: ' + r.title + '\n   URL: ' + r.link + '\n   EXTRAIT: ' + r.snippet
).join('\n\n');

const prompt = 'Tu es un expert en strategie de contenu digital pour psychologues et coachs bien-etre francophones.\n\n' +
  'Anna Ollivier est psychologue clinicienne qui developpe une formation en ligne sur la gestion emotionnelle et la confiance en soi. ' +
  'Elle publie sur YouTube, TikTok et Facebook mais peine a gagner de la visibilite.\n\n' +
  'Voici les resultats les mieux places sur Google pour ses thematiques cibles :\n\n' +
  concurrentsText + '\n\n' +
  'Analyse ces resultats et reponds avec un JSON valide, sans backtick ni commentaire :\n' +
  '{"themes_dominants":["theme1","theme2","theme3","theme4","theme5"],"angles_non_exploites":["angle1","angle2","angle3"],"formats_performants":["format1","format2","format3"],"mots_cles_opportunites":["mot1","mot2","mot3","mot4","mot5"],"mots_cles_utilises_concurrents":["mc1","mc2","mc3","mc4","mc5"],"plateformes_concurrents":["plateforme1","plateforme2"],"points_forts_concurrents":["pfc1","pfc2","pfc3"],"positionnement_anna":"Comment Anna se differencie en 2-3 phrases","produits_concurrents":[{"nom":"...","produit":"...","prix":"..."},{"nom":"...","produit":"...","prix":"..."}],"concurrents_principaux":[{"nom":"...","url":"...","point_fort":"..."},{"nom":"...","url":"...","point_fort":"..."}],"recommandations":["reco1","reco2","reco3"],"resume_veille":"Synthese de 4 phrases max"}';

const apiBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 2500,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { prompt, apiBody, nbConcurrents: allResults.length, dateVeille: new Date().toISOString().split('T')[0] } }];

const claudeResponse = $json;
let claudeText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  claudeText = claudeResponse.content[0].text || '';
} else {
  claudeText = JSON.stringify(claudeResponse);
}

let analysis = {};
try {
  analysis = JSON.parse(claudeText);
} catch(e) {
  const start = claudeText.indexOf('{');
  const end = claudeText.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    try { analysis = JSON.parse(claudeText.substring(start, end + 1)); } catch(e2) {}
  }
}

const prev = $('Combiner et Build Prompt').first().json;
const concurrents = (analysis.concurrents_principaux || []).map(c => c.nom + ' — ' + c.point_fort).join('\n');
const produitsConc = (analysis.produits_concurrents || []).map(p => p.nom + ': ' + p.produit + (p.prix ? ' (' + p.prix + ')' : '')).join('\n');

return [{
  json: {
    dateVeille: prev.dateVeille,
    nbConcurrents: prev.nbConcurrents,
    themesDominants: (analysis.themes_dominants || []).join('\n'),
    anglesNonExploites: (analysis.angles_non_exploites || []).join('\n'),
    formatsPerformants: (analysis.formats_performants || []).join('\n'),
    motsClesOpportunites: (analysis.mots_cles_opportunites || []).join(', '),
    motsClesUtilises: (analysis.mots_cles_utilises_concurrents || []).join(', '),
    plateformesConcurrents: (analysis.plateformes_concurrents || []).join(', '),
    pointsFortsConcurrents: (analysis.points_forts_concurrents || []).join('\n'),
    positionnementAnna: analysis.positionnement_anna || '',
    produitsConcurrents: produitsConc,
    concurrentsPrincipaux: concurrents,
    recommandations: (analysis.recommandations || []).join('\n'),
    resumeVeille: analysis.resume_veille || '',
    rawAnalysis: JSON.stringify(analysis)
  }
}];

